class UserRegistrationService {
  register(user: User) {
    const db = new DatabaseConnection();
    const smtp = new SmtpClient();
    db.insert(user);
    smtp.sendWelcome(user.email);
    Logger.log('registered', user.id);
  }
}

// Version A
class OrderOrchestrator {
  constructor(private validator: Validator, private gateway: PaymentGateway, private notifier: Notifier) {}
  process(order: Order) {
    if (!this.validator.isValid(order)) return;
    this.gateway.charge(order);
    this.notifier.notify(order);
  }
}

// Version B
class OrderService {
  process(order: Order) {
    const validator = new Validator();
    const gateway = new StripeGateway();
    const notifier = new EmailNotifier();
    if (!validator.isValid(order)) return;
    gateway.charge(order);
    notifier.notify(order);
  }
}
